<div
    x-data
    x-init="const controller = new AbortController(); let stopWaitingForTourElements = () => {}; const dismiss = () => Livewire.dispatch('capell-welcome-tour::dismiss'); const targetSelector = @js($currentTargetSelector); const chapterKey = @js($currentChapterKey); if (targetSelector && chapterKey) requestAnimationFrame(() => requestAnimationFrame(() => { if (! document.querySelector(targetSelector)) Livewire.dispatch('capell-welcome-tour::complete-chapter', { chapterKey }) })); if (@js($autoStart)) stopWaitingForTourElements = Livewire.on('filament-tour::loaded-elements', () => { stopWaitingForTourElements(); Livewire.dispatch('filament-tour::open-tour', { id: 'capell_admin_welcome.dashboard' }) }); document.addEventListener('click', (event) => { if (event.target.closest('.driver-popover-close-btn')) dismiss() }, { capture: true, signal: controller.signal }); document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && document.body.classList.contains('driver-active')) dismiss() }, { signal: controller.signal }); document.addEventListener('livewire:navigating', () => { stopWaitingForTourElements(); controller.abort() }, { once: true, signal: controller.signal })"
></div>
